#include "Studio.h"
#include <cstdlib>
#include <cmath>
namespace pulse {
using namespace juce;
namespace {
String stamp(const File& file){return file.getFullPathName()+"|"+String(file.getSize())+"|"+String(file.getLastModificationTime().toMilliseconds());}
class TranscriptionDialog final:public AlertWindow {
public:
    TranscriptionDialog(const String& message,const String& summary,bool busy,bool ready,Component* parent):AlertWindow("Audio to notes review",message,MessageBoxIconType::NoIcon,parent){auto area=parent->getParentMonitorArea();text.setComponentID("transcription-report");text.setMultiLine(true,true);text.setReadOnly(true);text.setScrollbarsShown(true);text.setText(summary,false);text.setSize(jmax(230,jmin(650,(int)(area.getWidth()*.54))),jmax(100,jmin(300,area.getHeight()-330)));addCustomComponent(&text);if(ready){addButton("Original",1);addButton("Notes",2);addButton("Stop",3);addButton("Apply",4);addButton("Settings",5);}addButton(busy?"Cancel task":"Discard",0,KeyPress(KeyPress::escapeKey));}
    bool refreshing=false;TextEditor text;
};
}
bool Studio::transcriptionCurrent()const{return !transcriptionTask&&!transcription.notes.empty()&&waveSample&&waveRevision==transcriptionWaveRevision&&revision==transcriptionProjectRevision&&waveFile==transcriptionSource;}
void Studio::stopTranscriptionAudition(bool republish){bool restore=transcriptionNoteAudition;transcriptionNoteAudition=false;if(restore)engine->stop();if(transcriptionOriginalAudition)engine->cancelPreview();transcriptionOriginalAudition=false;if(restore&&republish)publish();}
void Studio::discardTranscription(){transcriptionReveal=false;if(transcriptionTask){transcriptionTask->cancel.store(true);status="Cancelling audio-to-notes conversion...";return;}stopTranscriptionAudition();transcription={};transcriptionHash.clear();transcriptionStamp.clear();}
void Studio::showTranscriptionSettings(){
    closeCommandPalette();stopTranscriptionAudition();if(!waveSample||transcriptionTask||waveEditBusy||restorationTask||referenceTask||mixTask||recording||recorder.isActive()||exporting.load()||pendingNoteTool()){status="Open waveform audio, select a clean melody, and finish the current take/task/note preview first.";return;}
    auto* d=new AlertWindow("Audio to notes (monophonic)","Estimate one melody from the waveform selection (55-1600 Hz). Select 0.12-30 seconds fitting 64 beats. Review confidence and listen before Apply. Chords, drums, bends and overlapping instruments are not supported. Apply creates a new PAT pattern on the chosen channel; source audio and existing music remain intact.",MessageBoxIconType::NoIcon,this);
    StringArray channels;for(int i=0;i<(int)project.tracks.size();++i)channels.add(String(i+1)+". "+project.tracks[(size_t)i].name+(project.tracks[(size_t)i].isBus?" (bus)":""));int track=transcriptionCurrent()?transcriptionTrack:selectedTrack;if(project.tracks[(size_t)track].isBus||isDrum(project.tracks[(size_t)track].instrument))for(int i=0;i<(int)project.tracks.size();++i)if(!project.tracks[(size_t)i].isBus&&!isDrum(project.tracks[(size_t)i].instrument)){track=i;break;}
    d->addComboBox("track",channels,"Destination instrument channel");d->getComboBoxComponent("track")->setSelectedItemIndex(track);d->addTextEditor("gate",String(transcriptionOptions.gateDb,2),"AC RMS gate (-72 to -6 dBFS)");d->addTextEditor("confidence",String(transcriptionOptions.confidence*100,2),"Minimum periodicity (65-98%)");d->addTextEditor("minimum",String(transcriptionOptions.minMs,2),"Minimum note duration (40-500 ms)");d->addButton("Analyze selection",1,KeyPress(KeyPress::returnKey));d->addButton("Cancel",0,KeyPress(KeyPress::escapeKey));auto safe=Component::SafePointer<Studio>(this);auto rev=revision,wr=waveRevision;
    d->enterModalState(true,ModalCallbackFunction::create([safe,d,rev,wr](int answer){if(!safe||answer!=1)return;TranscriptionOptions o;o.bpm=safe->project.bpm;double* fields[]={&o.gateDb,&o.confidence,&o.minMs};const char* names[]={"gate","confidence","minimum"};for(int i=0;i<3;++i){auto text=d->getTextEditorContents(names[i]).trim();auto* begin=text.toRawUTF8();char* end=nullptr;*fields[i]=std::strtod(begin,&end);if(text.isEmpty()||end==begin||*end!=0){safe->status="Enter numeric transcription settings.";return;}}o.confidence/=100;safe->beginTranscription(o,d->getComboBoxComponent("track")->getSelectedItemIndex(),rev,wr,true);}),true);
}
bool Studio::beginTranscription(const TranscriptionOptions& options,int track,uint64_t expected,uint64_t expectedWave,bool reveal){
    stopTranscriptionAudition();if(expected!=revision||expectedWave!=waveRevision||!waveSample||transcriptionTask||waveEditBusy||restorationTask||referenceTask||mixTask||recording||recorder.isActive()||exporting.load()||pendingNoteTool()){status="Project/audio changed or app is busy. Reopen Audio to notes.";return false;}
    auto valid=validateTranscription(options);if(valid.failed()){status=valid.getErrorMessage();return false;}if(std::abs(options.bpm-project.bpm)>1e-8||track<0||track>=(int)project.tracks.size()||project.tracks[(size_t)track].isBus||project.patterns.size()>=maxPatterns){status="Choose an instrument channel, retain the current tempo and free one of the 32 patterns.";return false;}
    int first=jlimit(0,waveSample->audio.getNumSamples()-1,(int)std::llround(waveStart*waveSample->sampleRate)),end=jlimit(first+1,waveSample->audio.getNumSamples(),(int)std::llround(waveEnd*waveSample->sampleRate));double seconds=(end-first)/waveSample->sampleRate;if(seconds<.12||seconds>30||seconds*project.bpm/60>64+1e-7){status="Select 0.12-30 seconds fitting within 64 beats at the project tempo.";return false;}
    discardTranscription();transcriptionOptions=options;transcriptionTrack=track;transcriptionFirst=first;transcriptionEnd=end;transcriptionSource=waveFile;transcriptionWaveRevision=waveRevision;transcriptionProjectRevision=revision;transcriptionReveal=reveal;
    try{AudioBuffer<float> selected(2,end-first);for(int c=0;c<2;++c)selected.copyFrom(c,0,waveSample->audio,c,first,end-first);transcriptionTask=std::make_unique<TranscriptionTask>(std::move(selected),waveSample->sampleRate,first,waveFile,options);if(!transcriptionTask->startThread(Thread::Priority::low)){transcriptionTask.reset();status="Cannot start audio-to-notes worker.";return false;}}catch(const std::exception&){transcriptionTask.reset();status="Not enough resources to transcribe audio.";return false;}
    transcriptionMessage="Analyzing a monophonic waveform snapshot in the background...";status=transcriptionMessage;if(reveal)showTranscriptionReview();return true;
}
void Studio::finishTranscription(){
    if(!transcriptionTask){if(!transcription.notes.empty()&&!transcriptionCurrent())discardTranscription();return;}if(!transcriptionTask->done.load(std::memory_order_acquire))return;
    auto* d=dynamic_cast<TranscriptionDialog*>(Component::getCurrentlyModalComponent());bool show=transcriptionReveal;transcriptionReveal=false;auto result=transcriptionTask->result;bool cancelled=transcriptionTask->cancel.load();transcription=std::move(transcriptionTask->transcript);transcriptionHash=transcriptionTask->sourceHash;transcriptionStamp=transcriptionTask->sourceStamp;transcriptionTask.reset();
    if(cancelled||result.failed()||!transcriptionCurrent()||recording||recorder.isActive()||waveEditBusy||exporting.load()){discardTranscription();transcriptionMessage=cancelled?"Transcription cancelled. Source and music retained.":result.failed()?result.getErrorMessage():"Project or waveform changed. Analyze the selection again.";}
    else{auto saved=saveTranscriptionReport(root.getChildFile("data/transcription-report.json"),transcription,transcriptionOptions,transcriptionSource,transcriptionHash,transcriptionFirst,waveSample->sampleRate);transcriptionMessage="Estimated melody ready. Inspect uncertain notes, compare Original / Notes, then Apply or Discard.";if(saved.failed())transcriptionMessage+=" "+saved.getErrorMessage();}
    status=transcriptionMessage;if(d){d->refreshing=true;d->exitModalState(0);showTranscriptionReview();}else if(show&&!Component::getCurrentlyModalComponent())showTranscriptionReview();
}
bool Studio::auditionTranscription(bool notes){
    if(!transcriptionCurrent()||stamp(transcriptionSource)!=transcriptionStamp||recording||recorder.isActive()||exporting.load()||inputMonitor.load()){status="Preview changed or recording/export/input monitoring is active. Rebuild or turn monitoring off before audition.";return false;}if(!audioReady())return false;stopTranscriptionAudition();perform(stop);
    if(!notes){double peak=0;for(int c=0;c<2;++c)peak=jmax(peak,(double)waveSample->audio.getMagnitude(c,transcriptionFirst,transcriptionEnd-transcriptionFirst));float gain=(float)jmin(.7,peak>0?.98/peak:.7);transcriptionOriginalAudition=engine->preview(waveSample,transcriptionFirst/waveSample->sampleRate,transcriptionEnd/waveSample->sampleRate,gain);status=transcriptionOriginalAudition?"Original waveform selection audition (no project edit).":"Audition queue busy.";return transcriptionOriginalAudition;}
    Project candidate;auto valid=appendTranscription(project,transcription,transcriptionTrack,"Audio notes preview",candidate);if(valid.failed()){status=valid.getErrorMessage();return false;}candidate.loop=false;candidate.metronome=false;String warnings;valid=compilePlayback(candidate,assets,currentFile==File()?root:currentFile.getParentDirectory(),engine->exchange.beginWrite(),warnings);if(valid.failed()){status=valid.getErrorMessage();publish();return false;}engine->exchange.publish();transcriptionNoteAudition=true;engine->start();status="Estimated notes preview on "+project.tracks[(size_t)transcriptionTrack].name+". Temporary PAT only; Apply commits the new pattern.";return true;
}
bool Studio::applyTranscription(){
    if(!transcriptionCurrent()||stamp(transcriptionSource)!=transcriptionStamp||recording||recorder.isActive()||exporting.load()||waveEditBusy){status="Project/source changed or app is busy. Analyze again before Apply.";return false;}
    Project next;auto valid=appendTranscription(project,transcription,transcriptionTrack,"Audio notes - "+transcriptionSource.getFileNameWithoutExtension(),next);if(valid.failed()){status=valid.getErrorMessage();return false;}int count=(int)transcription.notes.size(),track=transcriptionTrack;stopTranscriptionAudition();perform(stop);bool applied=commitCopiedNotes(std::move(next),track,0,count);if(applied){discardTranscription();status=String(count)+" estimated notes added as a new PAT pattern. Correct them in Piano roll; one Undo restores the previous project. Source audio and local confidence report retained.";}return applied;
}
void Studio::showTranscriptionReview(){
    closeCommandPalette();bool busy=transcriptionTask!=nullptr,ready=transcriptionCurrent();String text=ready?transcriptionSummary(transcription):"Analyze a clean monophonic waveform selection. The detector estimates 55-1600 Hz pitch, unquantized timing, relative RMS velocity and periodicity. Original music remains unchanged until Apply. See the local transcription-report.json for the last source/confidence record; saved reports cannot Apply after restart.";
    auto* d=new TranscriptionDialog(transcriptionMessage,text,busy,ready,this);auto safe=Component::SafePointer<Studio>(this);
    d->enterModalState(true,ModalCallbackFunction::create([safe,d](int answer){if(!safe||d->refreshing)return;if(answer==1||answer==2){safe->auditionTranscription(answer==2);safe->transcriptionMessage=safe->status;safe->showTranscriptionReview();}else if(answer==3){safe->stopTranscriptionAudition();safe->transcriptionMessage="Audition stopped. Project notes retained.";safe->showTranscriptionReview();}else if(answer==4)safe->applyTranscription();else if(answer==5)safe->showTranscriptionSettings();else safe->discardTranscription();}),true);
}
}
